// This file is generated by AI.

// 文档落盘队列的断言 (issue #25 的第一处症状: 自动保存把编辑回退、撤回错乱)。
//
// 两个不变量:
//
// 1. 同一份文档的写入**按发起顺序**执行 —— 否则磁盘上留下的是"哪个先写完"的运气;
// 2. 落盘期间用户又敲了字 (内容已经变了) 时**不回执** —— 回执会把编辑器里的文档
//    倒退到写入前那一份, 刚敲的字消失, 还往撤销栈里塞一条整档替换。

import { describe, expect, it, vi } from 'vitest';

import { createDocumentSaver } from '../src/editor/document-saver';

/** 让出事件循环, 等排队中的写入真正开始 */
const tick = () => new Promise((resolve) => setTimeout(resolve, 0));

describe('createDocumentSaver', () => {
  it('写入串行执行, 落盘顺序与发起顺序一致', async () => {
    const written: string[] = [];
    const committed: string[] = [];
    let release!: () => void;
    const blocked = new Promise<void>((resolve) => (release = resolve));
    let text = 'v1';

    const saver = createDocumentSaver({
      read: () => text,
      write: async (value) => {
        written.push(value);
        if (written.length === 1) await blocked;
      },
      commit: (value) => committed.push(value),
    });

    const first = saver.save();
    // 第一次写入已经开始 (内容 v1), 但还没落地
    await tick();
    expect(written).toEqual(['v1']);

    text = 'v2';
    const second = saver.save();

    await tick();
    // 第一次还没落地, 第二次不许开始
    expect(written).toEqual(['v1']);
    expect(saver.pending).toBe(true);

    release();
    await Promise.all([first, second]);

    expect(written).toEqual(['v1', 'v2']);
    expect(committed).toEqual(['v2']);
    expect(saver.pending).toBe(false);
  });

  it('落盘期间内容变了就不回执 (否则编辑会被旧内容回退)', async () => {
    const committed: string[] = [];
    let release!: () => void;
    const blocked = new Promise<void>((resolve) => (release = resolve));
    let text = 'v1';

    const saver = createDocumentSaver({
      read: () => text,
      write: async () => blocked,
      commit: (value) => committed.push(value),
    });

    const saving = saver.save();
    await tick();
    // 用户没等自动保存, 继续敲字
    text = 'v1 后续输入';
    release();
    await saving;

    expect(committed).toEqual([]);
  });

  it('内容没变时按写出去的那一份回执', async () => {
    const committed: string[] = [];
    const saver = createDocumentSaver({
      read: () => 'v1',
      write: async () => {},
      commit: (value) => committed.push(value),
    });

    await saver.save();

    expect(committed).toEqual(['v1']);
  });

  it('写入失败走 onError, 不回执, 也不阻塞后续保存', async () => {
    const committed: string[] = [];
    const errors: unknown[] = [];
    let text = 'bad';

    const saver = createDocumentSaver({
      read: () => text,
      write: async (value) => {
        if (value === 'bad') throw new Error('磁盘只读');
      },
      commit: (value) => committed.push(value),
      onError: (error) => errors.push(error),
    });

    await saver.save();
    text = 'good';
    await saver.save();

    expect(errors).toHaveLength(1);
    expect(committed).toEqual(['good']);
  });

  it('写入抛错不会让队列卡死 (Promise 不会拒绝)', async () => {
    const saver = createDocumentSaver({
      read: () => 'v1',
      write: async () => {
        throw new Error('磁盘只读');
      },
      commit: () => {},
    });

    await expect(saver.save()).resolves.toBeUndefined();
    await expect(saver.save()).resolves.toBeUndefined();
  });

  it('内容在写入那一刻才读取, 排队中的保存不会写过时内容', async () => {
    const committed: string[] = [];
    const written: string[] = [];
    let text = 'v1';
    const saver = createDocumentSaver({
      read: () => text,
      write: async (value) => {
        written.push(value);
      },
      commit: (value) => committed.push(value),
    });

    // 三次保存排队时内容还是 v1, 但真正写入时已经是 v2
    const tail = [saver.save(), saver.save(), saver.save()];
    text = 'v2';
    await Promise.all(tail);

    expect(written).toEqual(['v2', 'v2', 'v2']);
    expect(committed).toEqual(['v2', 'v2', 'v2']);
  });
});
